function validar(){
  let ok = validarIdentidade();
  if(deps.some(d=>!d.nome.trim())){ avisar('Falta o nome de algum acompanhante.','erro'); ok = false; }

  const pedidas = 1 + deps.filter(d=>d.nome.trim()).length;
  if(jaConfirmado){
    avisar('Este telefone já confirmou presença. Para alterar ou cancelar, solicite à organização.','erro'); ok = false;
  } else if(capacidade.esgotado){
    avisar('Lotação esgotada: os ' + capacidade.limite + ' lugares já foram confirmados.','erro'); ok = false;
  } else if(pedidas > capacidade.vagas){
    avisar('Restam ' + capacidade.vagas + ' lugar(es) e você pediu ' + pedidas + '.','erro'); ok = false;
  }
  return ok;
}

function validarEspera(){
  let ok = validarIdentidade();
  if(naEspera){
    avisar('Este telefone já está na fila, na ' + naEspera.posicao + 'ª posição.','erro'); ok = false;
  }
  return ok;
}

